step.action:
Call MCP tool `execute_sql` with:
      - url: {{db_url}}
      - api_key: {{service_key}}
      - sql: "SELECT seq FROM public._schema_migrations ORDER BY seq;"

check.output:
⚠️ **Database Out of Sync**

        The following migrations exist locally but are NOT applied in database:
        {{#each pending}}
        - [{{seq}}] {{description}}
        {{/each}}

        Deploying without applying migrations may cause runtime errors.
